          "isSecret": false
        },
        {
          "name": "TOOL_SEARCH_MAX_RESULTS",
          "description": "Maximum tool search results returned by search_tools",
          "default": "5",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "MCP_HTTP_PORT",
          "description": "Port for HTTP server (default: 8000)",
          "default": "8000",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "MCP_TRANSPORT",
          "description": "MCP transport type (http for HTTP, stdio for stdio)",
          "value": "http",
          "isRequired": false,
          "isSecret": false
        }
      ]
    },
    {
      "registryType": "oci",
      "identifier": "ghcr.io/mhajder/ghostfolio-mcp:1.4.3",
      "transport": {
